  `add_wis` int(11) NULL DEFAULT 0,
  `add_cha` int(11) NULL DEFAULT 0,
  `add_hp` int(11) NULL DEFAULT 0,
  `add_mp` int(11) NULL DEFAULT 0,
  `add_mr` int(11) NULL DEFAULT 0,
  `add_sp` int(11) NULL DEFAULT 0,
  `add_hit` int(11) NULL DEFAULT 0,
  `add_dmg` int(11) NULL DEFAULT 0,
  `add_bow_hit` int(11) NULL DEFAULT 0,
  `add_bow_dmg` int(11) NULL DEFAULT 0,
  `add_base_dmg_small` int(11) NULL DEFAULT 0 COMMENT '小型傷害',
  `add_base_dmg_large` int(11) NULL DEFAULT 0 COMMENT '大型傷害',
  `add_ac` int(11) NULL DEFAULT 0,
  `add_dmg_redux` int(11) NULL DEFAULT 0,
  `add_dodge` int(11) NULL DEFAULT 0,
  `add_er` int(11) NULL DEFAULT 0,
  `add_bow_redux` int(11) NULL DEFAULT 0 COMMENT '遠距離減免',
  `add_melee_redux` int(11) NULL DEFAULT 0 COMMENT '近距離減免',
  `add_def_fire` int(11) NULL DEFAULT 0,
  `add_def_water` int(11) NULL DEFAULT 0,
  `add_def_wind` int(11) NULL DEFAULT 0,
  `add_def_earth` int(11) NULL DEFAULT 0,
  `add_regist_freeze` int(11) NULL DEFAULT 0,
  `add_regist_stone` int(11) NULL DEFAULT 0,
  `add_regist_sleep` int(11) NULL DEFAULT 0,
  `add_regist_stun` int(11) NULL DEFAULT 0,
  `add_regist_blind` int(11) NULL DEFAULT 0 COMMENT '失明耐性',
  `add_regist_sustain` int(11) NULL DEFAULT 0 COMMENT '持續耐性',
  `add_magic_dmg_modifier` int(11) NULL DEFAULT 0,
  `add_magic_hit` int(11) NULL DEFAULT 0,
  `add_magic_dmg_redux` int(11) NULL DEFAULT 0 COMMENT '魔法傷害減免',
  `add_stun_success` int(11) NULL DEFAULT 0 COMMENT '暈眩成功率',
  `add_potion_recovery` int(11) NULL DEFAULT 0 COMMENT '藥水恢復',
  `add_weight_reduction` int(11) NULL DEFAULT 0 COMMENT '重量減免',
  `add_pvp_dmg` int(11) NULL DEFAULT 0,
  `add_pvp_redux` int(11) NULL DEFAULT 0,
  `add_ignore_reduction` int(11) NULL DEFAULT 0,
  `add_boss_dmg` int(11) NOT NULL DEFAULT 0 COMMENT '對 BOSS 傷害加成',
  `add_boss_redux` int(11) NOT NULL DEFAULT 0 COMMENT '受到 BOSS 傷害減免%',
  `add_exp_rate` int(11) NULL DEFAULT 0,
  `add_adena_rate` int(11) NULL DEFAULT 0,
  `add_drop_rate` int(11) NULL DEFAULT 0,
  `add_hp_regen` int(11) NULL DEFAULT 0,
  `add_mp_regen` int(11) NULL DEFAULT 0,
  PRIMARY KEY (`item_objid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '玩家暗黑道具屬性' ROW_FORMAT = DYNAMIC;

