  PRIMARY KEY (`item_object_id`) USING BTREE,
  INDEX `key_receiver`(`receiver`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

