  `is_id` int(11) NULL DEFAULT NULL,
  `durability` int(11) NULL DEFAULT NULL,
  `charge_count` int(11) NULL DEFAULT NULL,
  `remaining_time` int(11) NULL DEFAULT NULL,
  `last_used` datetime NULL DEFAULT NULL,
  `bless` int(11) NULL DEFAULT NULL,
  `attr_enchant_kind` int(11) NULL DEFAULT NULL,
  `attr_enchant_level` int(11) NULL DEFAULT NULL,
  `gamno` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `greater` int(11) NULL DEFAULT 0 COMMENT '物品階級',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `key_id`(`clan_name`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of clan_warehouse
-- ----------------------------

-- ----------------------------
-- Table structure for clan_warehouse_history
-- ----------------------------
DROP TABLE IF EXISTS `clan_warehouse_history`;
CREATE TABLE `clan_warehouse_history`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '流水編號',
  `clan_id` int(10) UNSIGNED NOT NULL COMMENT '血盟編號',
  `char_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '角色名稱',
  `type` tinyint(2) NOT NULL COMMENT '領出: 1, 存入:0',
  `item_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '物品名稱',
  `item_count` int(10) NOT NULL COMMENT '數量',
  `record_time` datetime NOT NULL COMMENT '提領時間',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `char_name`(`char_name`) USING BTREE,
  INDEX `clan_id`(`clan_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '盟倉使用記錄' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of clan_warehouse_history
-- ----------------------------

-- ----------------------------
-- Table structure for log_ban_ip
-- ----------------------------
DROP TABLE IF EXISTS `log_ban_ip`;
CREATE TABLE `log_ban_ip`  (
  `ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `datetime` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`ip`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 3072 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_ban_ip
-- ----------------------------

-- ----------------------------
-- Table structure for log_chat
-- ----------------------------
DROP TABLE IF EXISTS `log_chat`;
CREATE TABLE `log_chat`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `char_id` int(10) NOT NULL,
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `clan_id` int(10) NOT NULL,
  `clan_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `locx` int(10) NOT NULL,
  `locy` int(10) NOT NULL,
  `mapid` int(10) NOT NULL,
  `type` int(10) NOT NULL,
  `target_account_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `target_id` int(10) NULL DEFAULT 0,
  `target_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `target_clan_id` int(10) NULL DEFAULT NULL,
  `target_clan_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `target_locx` int(10) NULL DEFAULT NULL,
  `target_locy` int(10) NULL DEFAULT NULL,
  `target_mapid` int(10) NULL DEFAULT NULL,
  `content` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `datetime` datetime NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `char_id`(`char_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_chat
-- ----------------------------

-- ----------------------------
-- Table structure for log_cn_shop
-- ----------------------------
DROP TABLE IF EXISTS `log_cn_shop`;
CREATE TABLE `log_cn_shop`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `itemname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `itemid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `selling_price` int(45) NOT NULL DEFAULT 0,
  `time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `pcobjid` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `town_id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 80 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_cn_shop
