-- ----------------------------
-- Table structure for log_enchant
-- ----------------------------
DROP TABLE IF EXISTS `log_enchant`;
CREATE TABLE `log_enchant`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '流水號',
  `道具物件編號` int(11) NOT NULL DEFAULT 0 COMMENT 'OBJID',
  `道具模板編號` int(11) NULL DEFAULT NULL COMMENT 'item_id',
  `角色編號` int(11) NULL DEFAULT NULL COMMENT '角色編號',
  `道具名稱` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '道具顯示名稱',
  `是否裝備中` int(11) NULL DEFAULT NULL COMMENT '是否裝備中 0否1是',
  `強化等級` int(11) NULL DEFAULT NULL COMMENT '強化等級',
  `充能次數` int(11) NULL DEFAULT NULL COMMENT '充能次數',
  `剩餘時間` int(11) NULL DEFAULT NULL COMMENT '剩餘時間',
  `祝福狀態` int(11) NULL DEFAULT NULL COMMENT '祝福狀態',
  `屬性強化種類` int(11) NULL DEFAULT NULL COMMENT '屬性強化種類',
  `屬性強化等級` int(11) NULL DEFAULT NULL COMMENT '屬性強化等級',
  `紀錄時間` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '寫入紀錄時間',
  `IP與MAC` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'IP 與 MAC',
  `來源類型` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=強化爆裝',
  `贖回狀態` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=未贖回,1=已贖回',
  `贖回角色` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '執行贖回的角色名',
  `贖回時間` datetime NULL DEFAULT NULL COMMENT '贖回完成時間',
  `贖回IP` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '贖回當下IP',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `索引_角色編號`(`角色編號`) USING BTREE,
  INDEX `索引_道具物件編號`(`道具物件編號`) USING BTREE,
  INDEX `idx_redeem_char_status_time`(`角色編號`, `贖回狀態`, `紀錄時間`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 6 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_enchant
-- ----------------------------

-- ----------------------------
-- Table structure for log_gambling
-- ----------------------------
DROP TABLE IF EXISTS `log_gambling`;
CREATE TABLE `log_gambling`  (
  `id` int(10) NOT NULL DEFAULT 0 COMMENT '場次編號',
  `adena` bigint(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '該場總下注金額（池子）',
  `rate` double(5, 2) NOT NULL DEFAULT 0.00 COMMENT '兌獎用的倍率',
  `gamblingno` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '{場次}-{冠軍 NPC 模板 ID}',
  `outcount` int(10) NOT NULL DEFAULT 0 COMMENT '還剩多少「張」可以兌（上限）',
  `優勝者` tinyint(4) NOT NULL DEFAULT 0 COMMENT '本場優勝跑道 (1~5；0 為舊資料)',
  `本場獎金` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '本場莊家應支出總獎金 = 冠軍下注額 × 賠率',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE,
  INDEX `idx_winner_lane`(`優勝者`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_gambling
-- ----------------------------

-- ----------------------------
-- Table structure for log_gmcommand
-- ----------------------------
DROP TABLE IF EXISTS `log_gmcommand`;
CREATE TABLE `log_gmcommand`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `gmobjid` int(11) NOT NULL,
  `gmname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `cmd` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `town_id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 17030 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of log_gmcommand
-- ----------------------------

-- ----------------------------
-- Table structure for log_ip_attacks
-- ----------------------------
DROP TABLE IF EXISTS `log_ip_attacks`;
CREATE TABLE `log_ip_attacks`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '攻擊類型',
  `detected_count` int(11) NOT NULL COMMENT '偵測到的次數',
  `log_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ip`(`ip`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

