-- ----------------------------
-- Table structure for log_lotto
-- ----------------------------
DROP TABLE IF EXISTS `log_lotto`;
CREATE TABLE `log_lotto`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `總獎金池` bigint(20) NOT NULL DEFAULT 0 COMMENT '當期累計獎金池（銷售票券會增加）',
  `場次編號` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '開獎場次編號 yyMMddHHmm',
  `開獎時間` datetime NOT NULL COMMENT '預計或實際開獎時間',
  `開獎號碼` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '開獎號碼 例 03-05-14-22-25',
  `已派出獎金` bigint(20) NOT NULL DEFAULT 0 COMMENT '實際兌獎已發出金額總額',
  `五星注數` int(11) NOT NULL DEFAULT 0 COMMENT '五星符合之彩票張數總計',
  `五星每注獎金` bigint(20) NOT NULL DEFAULT 0 COMMENT '五星每張應發金額（整數除法）',
  `四星注數` int(11) NOT NULL DEFAULT 0,
  `四星每注獎金` bigint(20) NOT NULL DEFAULT 0,
  `三星注數` int(11) NOT NULL DEFAULT 0,
  `三星每注獎金` bigint(20) NOT NULL DEFAULT 0,
  `二星注數` int(11) NOT NULL DEFAULT 0,
  `二星每注獎金` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round`(`場次編號`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 236 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '五星樂透開獎／獎池日誌' ROW_FORMAT = COMPACT;

