  `itemobjid` int(11) NULL DEFAULT 0 COMMENT '回收物品OBJID',
  `itemadena` int(11) NULL DEFAULT 0 COMMENT '单件物品回收金额',
  `itemcount` bigint(11) NULL DEFAULT 0 COMMENT '回收数量',
  `pcobjid` int(11) NULL DEFAULT 0 COMMENT '卖出者OBJID',
