  `id` int(11) NOT NULL AUTO_INCREMENT,
  `itemname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买入物品名称',
  `itemobjid` int(11) NULL DEFAULT 0 COMMENT '买入物品OBJID',
  `itemadena` int(11) NULL DEFAULT 0 COMMENT '单件物品买入金额',
  `itemcount` bigint(11) NULL DEFAULT 0 COMMENT '买入数量',
  `pcobjid` int(11) NULL DEFAULT 0 COMMENT '买入者OBJID',
  `pcname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买入者名称',
  `srcpcobjid` int(11) NULL DEFAULT 0 COMMENT '卖出者OBJID(个人商店)',
  `srcpcname` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卖出者名称(个人商店)',
  `trade_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=成功 0=失敗',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '失敗原因或備註',
  `datetime` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 11 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

