-- Records of server_傢俱
-- ----------------------------

-- ----------------------------
-- Table structure for server_城堡
-- ----------------------------
DROP TABLE IF EXISTS `server_城堡`;
CREATE TABLE `server_城堡`  (
  `castle_id` int(11) NOT NULL DEFAULT 0,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `war_time` datetime NULL DEFAULT NULL,
  `tax_rate` int(11) NOT NULL DEFAULT 0,
  `public_money` bigint(11) NOT NULL DEFAULT 0,
  `item_id` int(11) NOT NULL DEFAULT 0 COMMENT '攻城結束：盟主待領獎勯之物品編號（0=不發）',
  `count` int(11) NOT NULL DEFAULT 0 COMMENT '攻城結束：盟主待領獎勯之數量',
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '顯示用：城堡名=>道具名(數量)，與贊助 p_name 同類字串',
  `war_duration` int(11) NOT NULL DEFAULT 120 COMMENT '攻城持續時間(分鐘)',
  `war_interval` int(11) NOT NULL DEFAULT 5760 COMMENT '攻城週期循環時間(分鐘)',
  PRIMARY KEY (`castle_id`) USING BTREE,
  INDEX `castle_id`(`castle_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_城堡
-- ----------------------------

-- ----------------------------
-- Table structure for server_定時加倍
-- ----------------------------
DROP TABLE IF EXISTS `server_定時加倍`;
CREATE TABLE `server_定時加倍`  (
  `序號` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主鍵',
  `啟用` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0=停用本筆,1=啟用本筆',
  `名稱` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活動名稱',
  `週` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=每天,1=週一,2=週二,3=週三,4=週四,5=週五,6=週六,7=週日',
  `開始時間` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '00:00' COMMENT '24小時制HH:mm',
  `結束時間` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '23:59' COMMENT '24小時制HH:mm,可跨日',
  `加倍方案` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '1=經驗,2=金幣,3=掉寶,6=全部',
  `經驗倍率` decimal(8, 2) NOT NULL DEFAULT 1.00 COMMENT '經驗倍率',
  `金幣倍率` decimal(8, 2) NOT NULL DEFAULT 1.00 COMMENT '金幣倍率',
  `掉寶倍率` decimal(8, 2) NOT NULL DEFAULT 1.00 COMMENT '掉寶倍率',
  `開始公告` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '開始公告,空白=不公告',
  `結束公告` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '結束公告,空白=不公告',
  `備註` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理備註',
  PRIMARY KEY (`序號`) USING BTREE,
  INDEX `idx_定時加倍_時間`(`啟用`, `週`, `開始時間`, `結束時間`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定時加倍設定' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_定時加倍
-- ----------------------------

-- ----------------------------
-- Table structure for server_拍賣_紀錄
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄`;
CREATE TABLE `server_拍賣_紀錄`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '拍賣物品ID (主鍵)',
  `item_id` int(11) NOT NULL COMMENT '道具模板ID',
  `item_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '道具名稱',
  `count` bigint(10) NOT NULL DEFAULT 1 COMMENT '數量',
  `is_equipped` int(11) NOT NULL DEFAULT 0,
  `enchantlvl` int(11) NOT NULL DEFAULT 0,
  `is_id` int(11) NOT NULL DEFAULT 1,
  `durability` int(11) NOT NULL DEFAULT 0,
  `charge_count` int(11) NOT NULL DEFAULT 0,
  `remaining_time` int(11) NOT NULL DEFAULT 0,
  `last_used` datetime NULL DEFAULT NULL,
  `bless` int(11) NOT NULL DEFAULT 1,
  `attr_enchant_kind` int(11) NOT NULL DEFAULT 0,
  `attr_enchant_level` int(11) NOT NULL DEFAULT 0,
  `gamno` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `greater` int(11) NOT NULL DEFAULT 0 COMMENT '物品階級',
  `magic_stone_item_id` int(11) NOT NULL DEFAULT 0,
  `magic_stone_level` int(11) NOT NULL DEFAULT 0,
  `magic_stone_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_item_id`(`item_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '拍賣專用物品快照' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_拍賣_紀錄
-- ----------------------------

-- ----------------------------
-- Table structure for server_拍賣_紀錄_娃娃
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄_娃娃`;
CREATE TABLE `server_拍賣_紀錄_娃娃`  (
  `auction_item_id` int(11) NOT NULL COMMENT '對應 shop_拍賣_物品.id',
  `power_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '覺醒能力ID集合(逗號分隔)',
  PRIMARY KEY (`auction_item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '拍賣專用娃娃覺醒快照' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_拍賣_紀錄_娃娃
-- ----------------------------

-- ----------------------------
-- Table structure for server_拍賣_紀錄_打洞
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄_打洞`;
CREATE TABLE `server_拍賣_紀錄_打洞`  (
  `auction_item_id` int(11) NOT NULL COMMENT '對應 shop_拍賣_物品.id',
  `card_1` int(11) NOT NULL DEFAULT 0 COMMENT '第1孔',
  `card_2` int(11) NOT NULL DEFAULT 0,
  `card_3` int(11) NOT NULL DEFAULT 0,
  `card_4` int(11) NOT NULL DEFAULT 0,
  `card_5` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`auction_item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '拍賣專用打洞快照' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_拍賣_紀錄_打洞
-- ----------------------------

-- ----------------------------
-- Table structure for server_拍賣_紀錄_拖售
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄_拖售`;
CREATE TABLE `server_拍賣_紀錄_拖售`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '拍賣流水號',
  `item_obj_id` int(11) NOT NULL COMMENT '物品唯一ID',
  `auction_item_id` int(11) NULL DEFAULT NULL COMMENT '對應 shop_拍賣_物品.id (NULL=舊資料)',
  `item_id` int(11) NOT NULL COMMENT '物品模板ID (顯示用)',
  `item_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '物品名稱 (顯示用)',
  `count` int(11) NOT NULL DEFAULT 1 COMMENT '數量',
  `enchant` int(11) NOT NULL DEFAULT 0 COMMENT '強化等級',
  `bless` int(11) NULL DEFAULT 1,
  `seller_id` int(11) NOT NULL COMMENT '賣家ID',
  `seller_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '賣家名稱',
  `price` int(11) NOT NULL DEFAULT 0 COMMENT '目前價格',
  `bidder_id` int(11) NOT NULL DEFAULT 0 COMMENT '目前最高出價者',
  `bidder_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '最高出價者名稱',
  `deadline` datetime NOT NULL COMMENT '結標時間',
  `create_time` datetime NOT NULL COMMENT '建立時間',
  `store_status` int(2) NOT NULL DEFAULT 0 COMMENT '0:拍賣中 1:存入倉庫',
  `greater` int(11) NULL DEFAULT 0 COMMENT '物品階級',
  `attr_enchant_kind` int(11) NULL DEFAULT NULL,
  `attr_enchant_level` int(11) NULL DEFAULT NULL,
  `dark_item` int(11) NULL DEFAULT 0 COMMENT '暗黑道具 config_id (0=無)',
  `inlay_1` int(11) NULL DEFAULT 0 COMMENT '打洞1',
  `inlay_2` int(11) NULL DEFAULT 0 COMMENT '打洞2',
  `inlay_3` int(11) NULL DEFAULT 0 COMMENT '打洞3',
  `magic_stone_item_id` int(11) NOT NULL DEFAULT 0 COMMENT '魔石物品ID',
  `magic_stone_level` int(11) NOT NULL DEFAULT 0 COMMENT '魔石階級',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_deadline`(`deadline`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_拍賣_紀錄_拖售
-- ----------------------------

-- ----------------------------
-- Table structure for server_拍賣_紀錄_暗黑
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄_暗黑`;
CREATE TABLE `server_拍賣_紀錄_暗黑`  (
  `auction_item_id` int(11) NOT NULL COMMENT '對應 shop_拍賣_物品.id',
  `config_id` int(11) NOT NULL COMMENT '配置ID',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '頭銜名稱',
  `add_str` int(11) NOT NULL DEFAULT 0,
  `add_dex` int(11) NOT NULL DEFAULT 0,
  `add_con` int(11) NOT NULL DEFAULT 0,
  `add_int` int(11) NOT NULL DEFAULT 0,
  `add_wis` int(11) NOT NULL DEFAULT 0,
  `add_cha` int(11) NOT NULL DEFAULT 0,
  `add_hp` int(11) NOT NULL DEFAULT 0,
  `add_mp` int(11) NOT NULL DEFAULT 0,
  `add_mr` int(11) NOT NULL DEFAULT 0,
  `add_sp` int(11) NOT NULL DEFAULT 0,
  `add_hit` int(11) NOT NULL DEFAULT 0,
  `add_dmg` int(11) NOT NULL DEFAULT 0,
  `add_bow_hit` int(11) NOT NULL DEFAULT 0,
  `add_bow_dmg` int(11) NOT NULL DEFAULT 0,
  `add_ac` int(11) NOT NULL DEFAULT 0,
  `add_dmg_redux` int(11) NOT NULL DEFAULT 0,
  `add_dodge` int(11) NOT NULL DEFAULT 0,
  `add_er` int(11) NOT NULL DEFAULT 0,
  `add_def_fire` int(11) NOT NULL DEFAULT 0,
  `add_def_water` int(11) NOT NULL DEFAULT 0,
  `add_def_wind` int(11) NOT NULL DEFAULT 0,
  `add_def_earth` int(11) NOT NULL DEFAULT 0,
  `add_regist_freeze` int(11) NOT NULL DEFAULT 0,
  `add_regist_stone` int(11) NOT NULL DEFAULT 0,
  `add_regist_sleep` int(11) NOT NULL DEFAULT 0,
  `add_regist_stun` int(11) NOT NULL DEFAULT 0,
  `add_regist_blind` int(11) NOT NULL DEFAULT 0,
  `add_regist_sustain` int(11) NOT NULL DEFAULT 0,
  `add_base_dmg_small` int(11) NOT NULL DEFAULT 0,
  `add_base_dmg_large` int(11) NOT NULL DEFAULT 0,
  `add_magic_dmg_modifier` int(11) NOT NULL DEFAULT 0,
  `add_magic_hit` int(11) NOT NULL DEFAULT 0,
  `add_magic_dmg_redux` int(11) NOT NULL DEFAULT 0,
  `add_stun_success` int(11) NOT NULL DEFAULT 0,
  `add_potion_recovery` int(11) NOT NULL DEFAULT 0,
  `add_weight_reduction` int(11) NOT NULL DEFAULT 0,
  `add_bow_redux` int(11) NOT NULL DEFAULT 0,
  `add_melee_redux` int(11) NOT NULL DEFAULT 0,
  `add_pvp_dmg` int(11) NOT NULL DEFAULT 0,
  `add_pvp_redux` int(11) NOT NULL DEFAULT 0,
  `add_ignore_reduction` int(11) NOT NULL DEFAULT 0,
  `add_boss_dmg` int(11) NOT NULL DEFAULT 0,
  `add_boss_redux` int(11) NOT NULL DEFAULT 0,
  `add_exp_rate` int(11) NOT NULL DEFAULT 0,
  `add_adena_rate` int(11) NOT NULL DEFAULT 0,
  `add_drop_rate` int(11) NOT NULL DEFAULT 0,
  `add_hp_regen` int(11) NOT NULL DEFAULT 0,
  `add_mp_regen` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`auction_item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拍賣專用暗黑快照' ROW_FORMAT = COMPACT;

