-- ----------------------------
-- Table structure for server_拍賣_紀錄_領取
-- ----------------------------
DROP TABLE IF EXISTS `server_拍賣_紀錄_領取`;
CREATE TABLE `server_拍賣_紀錄_領取`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `auction_item_id` int(11) NULL DEFAULT NULL COMMENT '對應 shop_拍賣_物品.id (NULL=金幣或舊資料)',
  `char_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `count` bigint(20) NOT NULL,
  `enchant` int(11) NULL DEFAULT 0,
  `bless` int(11) NULL DEFAULT 1,
  `greater` int(11) NULL DEFAULT 0 COMMENT '物品階級',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `status` int(11) NULL DEFAULT 0 COMMENT '0:未領取 1:已領取',
  `claim_time` datetime NULL DEFAULT NULL,
  `attr_enchant_kind` int(11) NULL DEFAULT NULL,
  `attr_enchant_level` int(11) NULL DEFAULT NULL,
  `dark_item` int(11) NULL DEFAULT 0 COMMENT '暗黑道具 config_id (0=無)',
  `inlay_1` int(11) NULL DEFAULT 0 COMMENT '打洞1',
  `inlay_2` int(11) NULL DEFAULT 0 COMMENT '打洞2',
  `inlay_3` int(11) NULL DEFAULT 0 COMMENT '打洞3',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `char_id_idx`(`char_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_拍賣_紀錄_領取
-- ----------------------------

-- ----------------------------
-- Table structure for server_村莊
-- ----------------------------
DROP TABLE IF EXISTS `server_村莊`;
CREATE TABLE `server_村莊`  (
  `town_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `leader_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `leader_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `tax_rate` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `tax_rate_reserved` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sales_money` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sales_money_yesterday` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `town_tax` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `town_fix_tax` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `none` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`town_id`) USING BTREE,
  INDEX `town_id`(`town_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_村莊
-- ----------------------------

-- ----------------------------
-- Table structure for server_盟屋_佈告
-- ----------------------------
DROP TABLE IF EXISTS `server_盟屋_佈告`;
CREATE TABLE `server_盟屋_佈告`  (
  `id` int(10) NOT NULL DEFAULT 0,
  `name` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `date` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `title` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `content` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_盟屋_佈告
-- ----------------------------

-- ----------------------------
-- Table structure for server_盟屋_拍賣
-- ----------------------------
DROP TABLE IF EXISTS `server_盟屋_拍賣`;
CREATE TABLE `server_盟屋_拍賣`  (
  `house_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `house_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `house_area` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `deadline` datetime NULL DEFAULT NULL,
  `price` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `location` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `old_owner` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `old_owner_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `bidder` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `bidder_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`house_id`) USING BTREE,
  INDEX `house_id`(`house_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_盟屋_拍賣
-- ----------------------------

-- ----------------------------
-- Table structure for server_盟屋_紀錄
-- ----------------------------
DROP TABLE IF EXISTS `server_盟屋_紀錄`;
CREATE TABLE `server_盟屋_紀錄`  (
  `house_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `house_name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `house_area` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `location` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `keeper_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `is_on_sale` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `is_purchase_basement` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `tax_deadline` datetime NOT NULL,
  `locx1` int(10) NOT NULL DEFAULT 0 COMMENT '座标x1',
  `locx2` int(10) NOT NULL DEFAULT 0 COMMENT '座标x2',
  `locy1` int(10) NOT NULL DEFAULT 0 COMMENT '座标y1',
  `locy2` int(10) NOT NULL DEFAULT 0 COMMENT '座标y2',
  `locx3` int(10) NOT NULL DEFAULT 0 COMMENT '座标x3(用于不规则型小屋第2座标)',
  `locx4` int(10) NOT NULL DEFAULT 0 COMMENT '座标x4(用于不规则型小屋第2座标)',
  `locy3` int(10) NOT NULL DEFAULT 0 COMMENT '座标y3(用于不规则型小屋第2座标)',
  `locy4` int(10) NOT NULL DEFAULT 0 COMMENT '座标y4(用于不规则型小屋第2座标)',
  `mapid` int(10) NOT NULL DEFAULT 0 COMMENT '小屋地图编号',
  `basement` int(10) NOT NULL DEFAULT 0 COMMENT '地下盟屋地图编号',
  `homelocx` int(10) NOT NULL,
  `homelocy` int(10) NOT NULL,
  PRIMARY KEY (`house_id`) USING BTREE,
  INDEX `house_id`(`house_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_盟屋_紀錄
-- ----------------------------

-- ----------------------------
-- Table structure for server_紀錄_獎勵
-- ----------------------------
DROP TABLE IF EXISTS `server_紀錄_獎勵`;
CREATE TABLE `server_紀錄_獎勵`  (
  `流水號` int(11) NOT NULL AUTO_INCREMENT,
  `玩家帳號` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '玩家帳號',
  `發送物品編號` int(10) NOT NULL DEFAULT 0 COMMENT '物品ID',
  `道具名稱` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '道具名稱',
  `發送物品數量` int(10) NOT NULL DEFAULT 1 COMMENT '數量',
  `強化值` int(10) NOT NULL DEFAULT 0 COMMENT '裝備強化等級',
  `領取狀態` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=未領取 1=已領取',
  `領取玩家角色` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '領取時角色名',
  `領取時間` datetime NULL DEFAULT NULL COMMENT '領取時間',
  `ip` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '領取時IP',
  PRIMARY KEY (`流水號`) USING BTREE,
  INDEX `idx_account_status`(`玩家帳號`, `領取狀態`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '即時獎勵領取' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_紀錄_獎勵
-- ----------------------------

-- ----------------------------
-- Table structure for server_紀錄_贊助
-- ----------------------------
DROP TABLE IF EXISTS `server_紀錄_贊助`;
CREATE TABLE `server_紀錄_贊助`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(10) NOT NULL DEFAULT 44070,
  `p_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '44070',
  `count` int(10) NOT NULL DEFAULT 1,
  `account` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `isget` tinyint(1) NULL DEFAULT 0,
  `out` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=未領取 1=已領取',
  `play` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `time` datetime NULL DEFAULT NULL,
  `ip` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_紀錄_贊助
-- ----------------------------

-- ----------------------------
-- Table structure for server_boss出生
-- ----------------------------
DROP TABLE IF EXISTS `server_boss出生`;
CREATE TABLE `server_boss出生`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '召喚管理編號(同傳送btX)',
  `location` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '地點名稱 (備註用)',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '同時召喚數量',
  `npc_templateid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'BOSS NPC 模板編號',
  `group_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '召喚群組 ID',
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生 X 座標 (傳送目標)',
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出生 Y 座標 (傳送目標)',
  `heading` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '面向方向 (0~7)',
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '地圖編號',
  `next_spawn_time` datetime NULL DEFAULT NULL COMMENT '下次召喚時間',
  `spawn_interval` int(10) NULL DEFAULT 60000 COMMENT '重生間隔 (分鐘)',
  `exist_time` int(10) NULL DEFAULT 0 COMMENT '存在時間 (分鐘, 0=無限期)',
  `boss_group_type` int(10) NOT NULL DEFAULT 1 COMMENT 'BOSS 傳送分類 1～10，對應介面 B_GROUP_1～B_GROUP_10 與 bossseach_N',
  `teleport_item_id` int(10) NOT NULL DEFAULT 0 COMMENT '傳送消耗道具 ID；0 表示不扣道具',
  `teleport_count` int(10) NOT NULL DEFAULT 0 COMMENT '傳送消耗數量（配合 teleport_item_id）',
  `img` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '傳送清單圖示ID（對應 var img src，不含井字）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 118 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_boss出生
-- ----------------------------

-- ----------------------------
-- Table structure for server_drop限制
-- ----------------------------
DROP TABLE IF EXISTS `server_drop限制`;
CREATE TABLE `server_drop限制`  (
  `道具編號` int(11) NOT NULL COMMENT 'item_id',
  `備註` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=啟用限制',
  `間隔時間_分` int(11) NOT NULL DEFAULT 0 COMMENT '成功產出後冷卻分鐘數；0=僅統計不冷卻',
  `已產出數量` int(11) NOT NULL DEFAULT 0 COMMENT '全服累計產出（持久化）',
  `下次可產出時間` datetime NULL DEFAULT NULL COMMENT 'now < 此時間則整批拒絕',
  PRIMARY KEY (`道具編號`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '伺服器掉落產出限制（動態庫）' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of server_drop限制
-- ----------------------------

-- ----------------------------
-- Table structure for server_info
-- ----------------------------
DROP TABLE IF EXISTS `server_info`;
CREATE TABLE `server_info`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `minid` int(10) NULL DEFAULT 100000 COMMENT '預設最小ID編號',
  `maxid` int(10) NULL DEFAULT NULL COMMENT '目前已用最大ID編號',
  `start` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '服務器 啟動狀態',
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0.0.0.0',
  `port` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '2000',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'MyISAM free: 3072 kB' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of server_info
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;

-- LiTo idempotency key; NULL preserves every native/TW reward row.
ALTER TABLE `server_紀錄_獎勵`
  ADD COLUMN `lito_event_key` varchar(96) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL AFTER `ip`,
  ADD UNIQUE KEY `uq_lito_reward_event` (`lito_event_key`);
-- LiTo-owned rows make cross-client deletion safe.
CREATE TABLE IF NOT EXISTS `lito_character_origin` (
  `char_obj_id` int(10) unsigned NOT NULL,
  `account_name` varchar(50) NOT NULL,
  `char_name` varchar(45) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`char_obj_id`),
  UNIQUE KEY `uq_lito_character_name` (`char_name`),
  KEY `idx_lito_character_account` (`account_name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_account_origin` (
  `login` varchar(50) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`login`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_item_origin` (
  `item_obj_id` int(10) unsigned NOT NULL,
  `char_obj_id` int(10) unsigned NOT NULL,
  `catalog_id` int(11) NOT NULL,
  `tournament_reward` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`item_obj_id`),
  KEY `idx_lito_item_character` (`char_obj_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_warehouse_item_origin` (
  `item_obj_id` int(10) unsigned NOT NULL,
  `scope` varchar(16) NOT NULL,
  `owner_key` varchar(45) NOT NULL,
  `catalog_id` int(11) NOT NULL,
  `tournament_reward` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`item_obj_id`),
  KEY `idx_lito_warehouse_owner` (`scope`,`owner_key`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_buddy_group` (
  `char_obj_id` int(10) unsigned NOT NULL,
  `group_id` smallint(5) unsigned NOT NULL,
  `group_name` varchar(45) NOT NULL,
  PRIMARY KEY (`char_obj_id`,`group_id`),
  UNIQUE KEY `uq_lito_buddy_group_name` (`char_obj_id`,`group_name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_buddy_metadata` (
  `char_obj_id` int(10) unsigned NOT NULL,
  `buddy_id` int(10) unsigned NOT NULL DEFAULT 0,
  `buddy_name` varchar(45) NOT NULL,
  `target_source` varchar(45) NOT NULL DEFAULT '',
  `group_id` smallint(5) unsigned NOT NULL DEFAULT 1,
  `relationship_style` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `palette_offset` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `origin` varchar(45) NOT NULL DEFAULT '',
  PRIMARY KEY (`char_obj_id`,`buddy_name`),
  KEY `idx_lito_buddy_target` (`buddy_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_clan_metadata` (
  `clan_id` int(10) unsigned NOT NULL,
  `lito_owned` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `destroy_pending` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `snapshot_version` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`clan_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_castle_metadata` (
  `castle_id` tinyint(3) unsigned NOT NULL,
  `security_enabled` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `mercenary_0` int(10) unsigned NOT NULL DEFAULT 0,
  `mercenary_1` int(10) unsigned NOT NULL DEFAULT 0,
  `mercenary_2` int(10) unsigned NOT NULL DEFAULT 0,
  `mercenary_3` int(10) unsigned NOT NULL DEFAULT 0,
  `snapshot_version` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`castle_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_castle_security_settlement` (
  `castle_id` tinyint(3) unsigned NOT NULL,
  `war_start_millis` bigint(20) unsigned NOT NULL,
  `treasury_before` int(10) unsigned NOT NULL,
  `charge_adena` int(10) unsigned NOT NULL,
  `charged_adena` int(10) unsigned NOT NULL DEFAULT 0,
  `prepared` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `completed` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `settled_at` datetime NOT NULL,
  PRIMARY KEY (`castle_id`,`war_start_millis`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_house_auction_metadata` (
  `house_id` int(10) unsigned NOT NULL,
  `snapshot_version` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`house_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_board_topic` (
  `topic_id` int(10) unsigned NOT NULL,
  `author_obj_id` int(10) unsigned NOT NULL,
  `author_name` varchar(45) NOT NULL,
  `post_date` char(8) NOT NULL,
  `title` varchar(40) NOT NULL,
  `content` text NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`topic_id`),
  KEY `idx_lito_board_author` (`author_obj_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_tournament_profile` (
  `char_obj_id` int(10) unsigned NOT NULL,
  `char_name` varchar(45) NOT NULL,
  `profile_state` mediumtext NOT NULL,
  `snapshot_version` int(10) unsigned NOT NULL DEFAULT 1,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`char_obj_id`),
  UNIQUE KEY `uq_lito_tournament_character` (`char_name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_private_inventory` (
  `char_obj_id` int(10) unsigned NOT NULL,
  `inventory_state` mediumtext NOT NULL,
  `snapshot_version` int(10) unsigned NOT NULL DEFAULT 1,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`char_obj_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_hotel_lease_key` (
  `item_obj_id` int(10) unsigned NOT NULL,
  `show_id` int(10) unsigned NOT NULL,
  `npc_id` int(10) unsigned NOT NULL,
  `room_number` tinyint(3) unsigned NOT NULL,
  `meeting_hall` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `renter_obj_id` int(10) unsigned NOT NULL,
  `renter_identity` varchar(95) NOT NULL,
  `expires_at` bigint(20) unsigned NOT NULL,
  `released` tinyint(1) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`item_obj_id`),
  KEY `idx_lito_hotel_show` (`show_id`),
  KEY `idx_lito_hotel_occupancy` (`npc_id`,`released`,`expires_at`),
  KEY `idx_lito_hotel_renter` (`renter_obj_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `lito_water_dragon_pass` (
  `item_obj_id` int(10) unsigned NOT NULL,
  `show_id` int(10) unsigned NOT NULL,
  `room_number` tinyint(3) unsigned NOT NULL,
  `renter_obj_id` int(10) unsigned NOT NULL,
  `renter_identity` varchar(95) NOT NULL,
  `expires_at` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`item_obj_id`),
  UNIQUE KEY `uq_lito_water_dragon_show` (`show_id`),
  KEY `idx_lito_water_dragon_occupancy` (`room_number`,`expires_at`),
  KEY `idx_lito_water_dragon_renter` (`renter_obj_id`,`expires_at`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
